from contact_solver import OUT,mesh # Reuse only the declared reference specimen geometry.
def rows_after(lines,index,count): # Read an explicitly identified native numeric table.
    result=[] # Keep native row order within each increment.
    for line in lines[index+1:]: # Start immediately below the table header.
        values=line.split() # Split whitespace-separated native fields.
        if not values and not result: continue # Skip header spacing only.
        if not values or len(values)!=count: break # Stop when the native table terminates.
        try: result.append([float(v.replace('D','E')) for v in values]) # Preserve printed precision without rounding again.
        except ValueError: break # Reject nonnumeric headers as table data.
    return np.asarray(result,dtype=float) # Return an explicit numeric frame.
def parse(path): # Recover all solver frames without inventing contact-point correspondence.
    lines=path.read_text().splitlines();frames={} # Identify every native time-labelled table.
    for i,line in enumerate(lines): # Read native field and resultant headers.
        match=re.search(r'time\s+([0-9.Ee+\-]+)',line) # Require an explicit solver pseudo-time.
        if not match: continue # Ignore undocumented or unlabelled log text.
        time=float(match.group(1));frame=frames.setdefault(time,{'stats':[]}) # Group actual fields at one converged increment.
        if line.startswith(' displacements ('): frame['u']=rows_after(lines,i,4) # Read stable global nodal displacements.
        elif line.startswith(' forces ('): frame['rf']=rows_after(lines,i,4) # Read native nodal forces, interpreting supports separately.
        elif line.startswith(' relative contact displacement'): frame['cdis']=rows_after(lines,i,5) # Preserve slave element, face and local displacement components.
        elif line.startswith(' contact stress'): frame['cstr']=rows_after(lines,i,5) # Preserve actual normal and two tangential contact tractions.
        elif line.startswith(' total number of contact'): frame['contact_count']=int(rows_after(lines,i,1)[0,0]) # Check complete active contact-point coverage.
        elif line.startswith(' statistics for slave'): frame['stats'].append(rows_after(lines,i+2,6)[0]) # Preserve requested total, normal and shear resultants in native output order.
    return frames # Return only parsed source information.
def audit_case(folder): # Check native provenance, convergence and physical consistency independently.
    meta=json.loads((folder/'metadata.json').read_text());receipt=json.loads((folder/'receipt.json').read_text());frames=parse(folder/'contact.dat');xyz,elements,blocks=mesh(*meta['mesh_upper']);xyz=np.asarray(xyz);elements=np.asarray(elements)-1;lower,upper=blocks # Reconstruct only the declared geometry for pressure integration.
    source_hashes_ok=all(hashlib.sha256((folder/name).read_bytes()).hexdigest()==digest for name,digest in receipt['files'].items());records=[];arrays={};previous_u=0.;total_variation=0.;max_u=0. # Validate evidence before deriving labels.
    assert receipt['returncode']==0 and receipt['job_finished'] and not receipt['error_marker'] and source_hashes_ok # Reject partial, failed, or modified native evidence.
    for step_index,(time,frame) in enumerate(sorted(frames.items())): # Audit every actual converged frame rather than only attractive endpoints.
        assert all(key in frame for key in ['u','rf','cdis','cstr','contact_count']) and len(frame['stats'])==3 # Require every requested source field and resultant.
        u=frame['u'][:,1:];rf=frame['rf'][:,1:];cdis=frame['cdis'][:,2:];cstr=frame['cstr'][:,2:];assert u.shape==(len(xyz),3) and rf.shape==u.shape and cdis.shape==cstr.shape and len(cdis)==frame['contact_count'] # Reject missing source nodes or mismatched contact tables.
        assert np.array_equal(frame['u'][:,0],np.arange(1,len(xyz)+1)) and np.array_equal(frame['rf'][:,0],frame['u'][:,0]) and np.array_equal(frame['cdis'][:,:2],frame['cstr'][:,:2]) # Verify actual row identities within this snapshot.
        current=xyz+u;lower_ids=np.asarray(lower['nodes'])-1;drive_ids=np.asarray(upper['top_nodes'])-1;slave_ids=np.asarray(upper['bottom_nodes'])-1;pressure=meta['pressure_MPa']*min(time,1.);external=np.zeros(3) # Establish the independently known applied normal loading.
        for eid in upper['top_elements']: # Integrate the exact oriented area vector of every deformed loaded bilinear top face.
            vertices=current[elements[eid-1,4:8]];external-=pressure*.5*np.cross(vertices,np.roll(vertices,-1,axis=0)).sum(axis=0) # Apply follower pressure consistently with actual deformed geometry.
        support=rf[lower_ids].sum(axis=0);drive=rf[drive_ids].sum(axis=0);drive[2]=0.;force_scale=max(pressure*5000.,1.);cf=frame['stats'][0][:3];normal=frame['stats'][1][:3];shear=frame['stats'][2][:3];normal_size=float(np.linalg.norm(normal));shear_size=float(np.linalg.norm(shear));ux=float(u[drive_ids,0].mean());du=ux-previous_u;total_variation+=abs(du);max_u=max(max_u,abs(ux));previous_u=ux # Separate imposed shear reaction from free top normal nodal forces.
        pressure_contact=cstr[:,0];traction=np.linalg.norm(cstr[:,1:],axis=1);capacity=meta['mu']*pressure_contact;ratio=np.divide(traction,capacity,out=np.zeros_like(traction),where=capacity>1.e-12);pen=-cdis[:,0];balance=float(np.linalg.norm(support+drive+external)/force_scale);reaction_error=float(np.linalg.norm(support-cf)/force_scale);normal_law=float(np.max(np.abs(pressure_contact-meta['normal_stiffness_N_per_mm3']*pen))/max(pressure_contact.max(),1.)) # Define positive penetration from independently verified negative normal CDIS in this solver.
        stage=int(np.ceil(time-1.e-8));record={'case':folder.name,'time':time,'stage':stage,'ux_drive_mm':ux,'increment_ux_mm':du,'cumulative_abs_ux_mm':total_variation,'historical_max_abs_ux_mm':max_u,'pressure_MPa':pressure,'mu':meta['mu'],'normal_N':normal_size,'shear_N':shear_size,'contact_fx_N':float(cf[0]),'drive_fx_N':float(drive[0]),'slave_mean_ux_mm':float(u[slave_ids,0].mean()),'slave_min_ux_mm':float(u[slave_ids,0].min()),'slave_max_ux_mm':float(u[slave_ids,0].max()),'pressure_min_MPa':float(pressure_contact.min()),'pressure_max_MPa':float(pressure_contact.max()),'penetration_max_mm':float(pen.max()),'raw_cdis_normal_max_mm':float(cdis[:,0].max()),'relative_tangential_max_mm':float(np.linalg.norm(cdis[:,1:],axis=1).max()),'coulomb_ratio_max':float(ratio.max()),'local_saturated_fraction':float(np.mean(ratio>0.999)),'contact_points':len(cdis),'force_balance_relative':balance,'reaction_contact_relative':reaction_error,'normal_law_relative':normal_law,'resultant_coulomb_ratio':shear_size/max(meta['mu']*normal_size,1.e-30)} # Retain path descriptors and physical diagnostics without calling them a learned operator.
        records.append(record);prefix=f'frame_{step_index:03d}_';arrays.update({prefix+'u':u,prefix+'rf':rf,prefix+'contact_element_face':frame['cdis'][:,:2].astype(int),prefix+'cdis':cdis,prefix+'cstr':cstr,prefix+'contact_resultants':np.asarray(frame['stats'])}) # Save exact snapshot labels; integration rows are not persistent IDs across remeshing.
    endpoints={str(i):next(r for r in records if abs(r['time']-i)<1.e-7) for i in range(1,5)};checks={'source_hashes_unchanged':source_hashes_ok,'four_stages_complete':len(endpoints)==4,'all_nodes_and_contact_rows_complete':True,'force_balance_relative_lt_1e-4':max(r['force_balance_relative'] for r in records)<1.e-4,'support_contact_relative_lt_2e-6':max(r['reaction_contact_relative'] for r in records)<2.e-6,'normal_law_relative_lt_2e-6':max(r['normal_law_relative'] for r in records)<2.e-6,'local_coulomb_ratio_le_1p000005':max(r['coulomb_ratio_max'] for r in records)<1.000005,'positive_contact_pressure':min(r['pressure_min_MPa'] for r in records)>0.,'micro_shear_global_unsaturated':endpoints['2']['resultant_coulomb_ratio']<.1,'forward_and_reverse_slip_saturated':all(abs(endpoints[str(i)]['resultant_coulomb_ratio']-1.)<2.e-5 for i in [3,4]),'forward_and_reverse_actual_relative_slip':endpoints['3']['slave_mean_ux_mm']>.09 and endpoints['4']['slave_mean_ux_mm']<-.09,'reversed_friction_force':endpoints['3']['contact_fx_N']<0. and endpoints['4']['contact_fx_N']>0.} # Declare physically meaningful tolerances including native contact-print precision.
    arrays['times']=np.asarray([r['time'] for r in records]);np.savez_compressed(folder/'labels.npz',**arrays);summary={'case':folder.name,'frame_count':len(records),'checks':checks,'all_checks_pass':all(checks.values()),'max_force_balance_relative':max(r['force_balance_relative'] for r in records),'max_reaction_contact_relative':max(r['reaction_contact_relative'] for r in records),'max_normal_law_relative':max(r['normal_law_relative'] for r in records),'max_coulomb_ratio':max(r['coulomb_ratio_max'] for r in records),'endpoints':endpoints,'metadata':meta} # Retain the full acceptance record and exact solver-backed label arrays.
    (folder/'audit.json').write_text(json.dumps(summary,indent=2)+'\n');return summary,records # Save reproducible case-level evidence before aggregation.
def figures(records,summaries): # Render actual load path data and an exact assumed specimen drawing.
    fig,axes=plt.subplots(1,3,figsize=(15,4.5),layout='constrained') # Allocate comparable scientific panels.
    for name in ['baseline_mu03_p10','mu02_p10_verified','mu04_p10']: # Compare only hash-verified cases at the same normal pressure and geometry.
        data=[r for r in records if r['case']==name];axes[0].plot([r['ux_drive_mm'] for r in data],[r['drive_fx_N']/1000 for r in data],'.-',label=name.split('_')[0]) # Display native cyclic tangential reactions without fitted data.
    base=[r for r in records if r['case']=='baseline_mu03_p10'];axes[1].plot([r['time'] for r in base],[r['normal_N']/1000 for r in base],'.-',label='normal force');axes[1].plot([r['time'] for r in base],[r['shear_N']/1000 for r in base],'.-',label='shear magnitude');axes[2].plot([r['time'] for r in base],[r['penetration_max_mm']*1000 for r in base],'.-',label='maximum penetration') # Plot true pressure ramp, slip saturation, and penalty penetration.
    for ax in axes: ax.grid(alpha=.25);ax.legend(fontsize=8) # Keep plots legible without obscuring evidence.
    axes[0].set(xlabel='Imposed upper displacement [mm]',ylabel='Tangential reaction [kN]',title='Actual friction path');axes[1].set(xlabel='Load-path pseudo-time',ylabel='Contact resultant [kN]',title='Compression and sliding');axes[2].set(xlabel='Load-path pseudo-time',ylabel='Penetration [micrometres]',title='Penalty compliance');fig.savefig(OUT/'contact_load_paths.png',dpi=180);fig.savefig(OUT/'contact_load_paths.pdf');plt.close(fig) # Export reusable solver-backed scientific figures.
    fig,ax=plt.subplots(figsize=(11,5),layout='constrained');ax.add_patch(plt.Rectangle((-10,-10),120,10,facecolor='#bcc8d7',edgecolor='black',hatch='//'));ax.add_patch(plt.Rectangle((0,0),100,10,facecolor='#dceafa',edgecolor='black')) # Draw exact nominal dimensions as an engineering specimen schematic, not a stress contour.
    for x in np.linspace(5,95,10): ax.annotate('',xy=(x,10),xytext=(x,17),arrowprops={'arrowstyle':'->','color':'#aa2222'}) # Identify the uniform top pressure direction.
    ax.plot([0,100],[0,0],color='#db8a00',lw=3,label='Real frictional interface: independent node sets');ax.annotate('imposed x: 0 → 0.00001 → +0.1 → −0.1 mm',xy=(65,6),xytext=(5,28),arrowprops={'arrowstyle':'->'});ax.text(50,20,'p = 5, 10, or 20 MPa',ha='center');ax.text(50,5,'Upper steel: 100 × 50 × 10 mm',ha='center');ax.text(50,-6,'Lower support: 120 × 70 × 10 mm; all nodes fixed',ha='center');ax.annotate('',xy=(0,-17),xytext=(100,-17),arrowprops={'arrowstyle':'<->'});ax.text(50,-16,'100 mm',ha='center');ax.text(-8,32,'CONTACT VERIFICATION SPECIMEN — assumed geometry; not a bridge construction drawing',fontsize=10,weight='bold');ax.set(xlim=(-15,120),ylim=(-23,37),aspect='equal',xlabel='x [mm]',ylabel='z [mm]');ax.legend(loc='lower left',fontsize=8);ax.grid(alpha=.15);fig.savefig(OUT/'contact_specimen_drawing.svg');fig.savefig(OUT/'contact_specimen_drawing.pdf');fig.savefig(OUT/'contact_specimen_drawing.png',dpi=180);plt.close(fig) # Deliver dimensions and load/support assumptions separately from numerical result plots.
def main(): # Aggregate complete native cases with independent checks and reusable state labels.
    summaries=[];records=[] # Preserve every solved parameter case and increment.
    for folder in sorted(OUT.iterdir()): # Detect actual completed case directories only.
        if folder.name in ['baseline_mu03_p10','mu02_p10_verified','mu04_p10','mu03_p05','mu03_p20','refined_mu03_p10','stiff_mu03_p10']: summary,data=audit_case(folder);summaries.append(summary);records.extend(data) # Explicitly approve only known runs; exclude corrupted or unexpectedly restored directories.
    with (OUT/'path_labels.csv').open('w',newline='') as handle: writer=csv.DictWriter(handle,fieldnames=list(records[0]));writer.writeheader();writer.writerows(records) # Provide transparent scalar labels for independent inspection and later modelling.
    comparison={s['case']:{'normal_N':s['endpoints']['3']['normal_N'],'shear_N':s['endpoints']['3']['shear_N'],'penetration_max_mm':s['endpoints']['3']['penetration_max_mm'],'slave_mean_ux_mm':s['endpoints']['3']['slave_mean_ux_mm']} for s in summaries};report={'scope':'Actual contact verification and solver-backed path labels only; no contact neural operator trained here. Not an as-built bridge capacity assessment.','case_count':len(summaries),'frame_count':len(records),'all_checks_pass':all(s['all_checks_pass'] for s in summaries),'cases':summaries,'mesh_penalty_comparison':comparison,'raw_cdis_sign':'This executable prints negative normal CDIS for penetration; verified against deformed bottom-node z and pressure = stiffness * (-CDIS_normal). Raw values are retained.','path_state_definition':'Stable nodal states U/RF and load-path descriptors are retained. CSTR/CDIS rows retain slave element/face ownership but not persistent quadrature identities; face-contact remeshing changes point counts. Complete hidden friction-history variables are not exported; these snapshots alone must not be claimed a complete Markov state.','sources':['https://www.feacluster.com/CalculiX/ccx_2.18/doc/ccx/input_deck_viewer.php?input_deck=friction3.inp','https://www.feacluster.com/CalculiX/ccx_2.18/doc/ccx/node143.html','https://www.feacluster.com/CalculiX/ccx_2.18/doc/ccx/node237.html','https://www.feacluster.com/CalculiX/ccx_2.18/doc/ccx/node277.html','https://www.dhondt.de/ccx_2.21.pdf']} # Explicitly distinguish useful contact evidence from unsupported operator or engineering claims.
    (OUT/'REPORT.json').write_text(json.dumps(report,indent=2)+'\n');figures(records,summaries);print(json.dumps({'case_count':len(summaries),'frame_count':len(records),'all_checks_pass':report['all_checks_pass'],'failed_checks':{s['case']:[k for k,v in s['checks'].items() if not v] for s in summaries if not s['all_checks_pass']}},indent=2)) # Save reviewable aggregate evidence and expose only concise results.
